headers = cli.Text("header", cli.setVerboseName("替换/添加请求头"), cli.setDefault(<<<HEAD
Cookie:test cookie
X-Forwarded-For:127.0.0.1

HEAD), cli.setRequired(true))
cli.check()

hijackHTTPRequest = func(isHttps, url, req, forward /*func(modifiedRequest []byte)*/, drop /*func()*/) {
    for i in headers.Split("\n"){
        #如果该行为空,则跳过
        if i == "" {
                continue
            }
        #解析析出请求头的参数和值
        key=i.Split(":")[0]
        value=''
        if len(i.Split(":"))>= 2{
            value=str.TrimSpace(str.Join(i.Split(":")[1:], nil))
        }
        req = poc.ReplaceHTTPPacketHeader(req, key, value)
    }
    db.SaveHTTPFlowFromRawWithOption(url /*type: string*/, req /*type: []byte*/, nil)
    forward(req)
}
